SELECT 'Y' isAutoReceive,/** 是否自动接收 **/ A.Entrust_Id entrustId,/*委托代码*/ A.CREATE_TIME createTime,/*创建时间*/ A.UPDATE_TIME updateTime,/*修改时间*/ A.PORTFOLIO_ID portfolioId,/*组合代码*/ B.PORTFOLIO_NAME PORTFOLIONAME,/**组合名称*/ A.FINPROD_ID FINPRODID,/**金融产品代码*/ CASE WHEN A.PS IN ('03','04') AND A.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN A.FINPROD_ID ELSE C.FINPROD_ABBR END FINPRODABBR,/**金融产品简称*/ CASE WHEN A.PS IN ('03','04') AND A.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN A.FINPROD_ID ELSE C.FINPROD_NAME END FINPRODNAME,/**金融产品全称*/ A.FINPROD_TYPE2 FINPRODTYPE2,/**资产类型*/ F.DEAL_CUR_ACCT ACCTNO, /*E.ACCT_NO ACCTNO,*/ /**网点账号*/ E.CCY ,/**币种*/ E.BUSI_ACCT_NO BUSIACCTNO,/**资金账号*/ E.ACCT_NAME ACCTNAME,/**户名*/ G.SEC_ACCT_ID SECACCTID,/**证券账户代码*/ G.SEC_ACCT_NAME SECACCTNAME,/**证券账户名称*/ G.BOND_ID stockHolderNo,/**股东代码*/ A.TRADE_MARKET TRADEMARKET,/*交易场所*/ A.TRADE_PLAT TRADEPLAT,/*交易平台*/ NVL(C.FINPROD_MARKET_ID,A.STOCK_ID) FINPRODMARKETID,/*市场代码*/ A.PS, /*交易方向*/ CASE WHEN A.TRADE_PLAT='03'/**交易平台 = 固定收益平台*/ THEN CASE WHEN F.DEAL_MODE='PRM05' THEN '' /*** 交易方式 = 不指定*/ WHEN F.DEAL_MODE='PRM07' THEN 'FI1' /*** 交易方式 = 定价申报*/ WHEN F.DEAL_MODE='PRM08' THEN 'FI3' /*** 交易方式 = 点击成交申报*/ WHEN F.DEAL_MODE='PRM13' THEN 'FI100JY' /*** 交易方式 = 可转换成交申报*/ WHEN F.DEAL_MODE='PRM12' THEN 'FI101JY' /*** 交易方式 = 最优价成交申报*/ WHEN F.DEAL_MODE='PRM14' THEN 'FI9' /*** 交易方式 = 指定对手方成交申报*/ ELSE '' END WHEN A.TRADE_PLAT='02' /**交易平台 = 竞价交易平台*/ THEN F.DEAL_MODE ELSE /**交易平台 = 大宗交易平台 OR 交易平台 = 综合协议平台*/ CASE WHEN F.DEAL_MODE='PRM05' THEN '' /*** 交易方式 = 不指定*/ WHEN F.DEAL_MODE='PRM06' THEN 'a' /*** 交易方式 = 意向申报*/ WHEN F.DEAL_MODE='PRM07' THEN 'b' /*** 交易方式 = 定价申报*/ WHEN F.DEAL_MODE='PRM08' THEN 'e' /*** 交易方式 = 点击成交申报*/ WHEN F.DEAL_MODE='PRM09' THEN 'c' /*** 交易方式 = 成交申报*/ WHEN F.DEAL_MODE='PRM10' THEN 'AFC' /*** 交易方式 = 收盘价固定价格申报*/ WHEN F.DEAL_MODE='PRM11' THEN 'AFW' /*** 交易方式 = 日均价固定价格申报*/ ELSE '' END END DEALMODE,/*交易方式*/ A.COUNTER_ID COUNTERID,/*交易对手*/ F.COUNTER_SEAT counterSeat,/**对手席位*/ A.COUNTER_TRADER COUNTERTRADER,/**对手方交易员*/ A.CONTACT_INFO CONTACTINFO,/**对手方联系方式*/ F.counter_org counterDealerId,/**对手方交易商代码*/ F.COUNTER_CON_NO appointmentNumber,/**约定号*/ '' dealNo,/**成交编号*/ '' trdMatchId,/**初始交易编号*/ '' quoterefId,/**交易所请求号*/ A.ENTRUST_DATE tradeDate,/**委托日期*/ A.VDATE,/**委托开始日*/ A.Mdate,/**委托结束日*/ DECODE(F.TARGET_TYPE,'02',A.ENTRUST_AMT,0) entrustAmt,/**委托额度*/ DECODE(F.TARGET_TYPE,'01',A.ENTRUST_NUM,0) entrustNum,/**委托数量*/ A.ENTRUST_STATUS entrustStatus,/**委托状态*/ CASE WHEN A.PS IN ('03','04','T68','T69') THEN A.PRICE*100 ELSE A.PRICE END entrustPrice,/**委托单价*/ A.INV_AIM invAim,/**投资目的*/ null fullPrice,/**全价*/ A.PRICE_MODEL priceMode,/**限价模式 */ FS.finishamt entrustLeftAmt,/*已完成数量*/ F.SETTLE_SPREED settleSpeed,/**清算速度*/ F.VDATE valueDate,/**起息日*/ F.VDATE2 valueDate2,/**起息日2*/ F.MDATE maturityDate,/**到期日*/ F.MDATE2 maturityDate2,/**到期日2*/ F.TERM_DAYS termDays,/**期限天数*/ F.TERM_DAYS2 termDays2,/**期限天数2*/ F.PURCH_TYPE purchType,/**申购类型*/ F.Min_Amt minAmt,/**最低成交金额*/ C2.FINPROD_ID tarFinprodId,/**目标金融产品代码*/ C2.FINPROD_ABBR tarinprodAbbr,/**目标金融产品简称*/ C2.FINPROD_MARKET_ID tarinprodMarketId,/**目标金融产品市场代码*/ H.Trader tradeId,/**交易员编号 */ I.Real_Name traderName,/**交易员姓名 */ I2.Real_Name invManagerId,/**投资经理*/ F.ASSET_TYPE assetType,/**资产类型*/ F.ASSET_TYPE1 assetType1,/**资产二级分类*/ F.ASSET_TYPE_10 assetType10,/**资产三级分类*/ F.ASSET_TYPE_11 assetType11,/**资产四级分类*/ A.Sale_Code saleCode,/*配售代码*/ T5.FINPROD_MARKET_ID conShareId,/*转股代码*/ T4.CON_PRICE conPrice,/*转股价格*/ F.EXP_CON_NUM conNum,/*转股数量*/ DECODE(H.IS_APPROVAL,'Y','1','N','0','') approverFlage,/*审批标志*/
F.TRADER ourTrader,/*本方交易员*/ btm.OUTPUT_VALUE_1 busiTypeTg FROM ETR_ENTRUST A LEFT JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID=B.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT C ON A.FINPROD_ID=C.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD F ON A.ENTRUST_ID = F.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO G ON F.SEC_ACCT_ID = G.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO E ON A.DEAL_CUR_ACCT = E.ACCT_NO LEFT JOIN ETR_DISTRIBUTE H ON A.ENTRUST_ID=H.ENTRUST_ID LEFT JOIN Sys_User I ON H.TRADER=I.USER_NAME LEFT JOIN Sys_User I2 ON A.INV_MANAGER_ID=I2.USER_NAME LEFT JOIN FIN_PRODUCT C2 ON F.R_FINPROD_ID=C2.FINPROD_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE T4 ON A.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT T5 ON T4.CON_FINPROD_ID = T5.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON ( A.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 IS NULL) AND ( A.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 IS NULL) AND ( A.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN ( select entrust_id, NVL(sum(finish_amt),0) finishamt from etr_finish_status group by entrust_id )FS ON FS.entrust_id = A.ENTRUST_ID
1=1 AND A.TRADE_MARKET in ('03','04')
AND A.Entrust_Id = #{entrustId}
AND A.Entrust_Id IN
#{entrustId}
AND A.PORTFOLIO_ID = #{portfolioId}
AND A.ENTRUST_STATUS = #{entrustStatus}
AND H.TRADER IN
#{trader}
AND A.TRADE_MARKET = #{tradeMarket}
AND A.TRADE_PLAT = #{tradePlat}
AND C.FINPROD_MARKET_ID = #{finprodMarketId}
AND A.PS = #{ps}
